import React, { useEffect } from 'react';
import './Home.css';
import { Link } from 'react-router-dom';
import AOS from 'aos';
import 'aos/dist/aos.css';

const Home = () => {
  useEffect(() => {
    // AOS fade/zoom animations
    AOS.init({ duration: 1000 });

    // ★ Scroll‑aware navbar
    const header = document.querySelector('header');

    const handleScroll = () => {
      const halfway = window.innerHeight / 2;           // half the viewport
      if (window.scrollY > halfway) {
        header.style.top = '-120px';                    // hide (slides up)
      } else {
        header.style.top = '0';                         // show
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      {/* ─── Navbar ───────────────────────────── */}
      <header>
        <nav className="container">
          <Link to="/" className="logo">
            <div className="logo-icon">M+</div>
            MEDIVAULT
          </Link>

          <ul className="nav-links">
            <li><a href="#home">Home</a></li>
            <li><a href="#about">About</a></li>
            <li><a href="#features">Features</a></li>
            <li><a href="#security">Security</a></li>
            <li><a href="#contact">Contact</a></li>
          </ul>

          <div className="auth-buttons">
            <Link to="/login" className="login-btn">Login</Link>
            <Link to="/register" className="signup-btn"><span>Sign Up</span></Link>
          </div>
        </nav>
      </header>

      {/* ─── Hero, Features, CTA, Footer (unchanged) ─── */}
      {/* … your existing JSX exactly as before … */}
    </>
  );
};

export default Home;
